INSERT INTO hotel (hotel_id, names, descriptions, address, city_id, star_rating) VALUES (81, 'Nurturing Nest Mineral Hot Springs and Spa', '<p><b>Property Location</b> <br />Located in Desert Hot Springs, Nurturing Nest Mineral Hot Springs and Spa is a 4-minute drive from Cabot''s Pueblo Museum and 6 minutes from Desert Hot Springs Town Center.  This resort is 9.7 mi (15.7 km) from Palm Springs Air Museum and 11 mi (17.7 km) from Palm Springs Aerial Tramway.</p><p><b>Rooms</b> <br />Make yourself at home in one of the 7 air-conditioned rooms featuring refrigerators. Complimentary wireless Internet access is available to keep you connected. Bathrooms have showers and complimentary toiletries.</p><p><b>Amenities</b> <br />Do''t miss out on the many recreational opportunities, including hot springs, an indoor pool, and a spa tub.</p><p><b>Dining</b> <br />For your convenience, a complimentary breakfast is served daily from 7:30 AM to 11 AM.</p><p><b>Business, Other Amenities</b> <br />Free self parking is available onsite.</p>', '11149 Sunset Ave Desert Hot SpringsCalifornia 92240 ', 81, 3);
