INSERT INTO hotel (hotel_id, names, descriptions, address, city_id, star_rating) VALUES (259, 'Americas Best Value Inn Bell Tower', '<p><b>Property Location</b> <br />Located in Centralia, Americas Best Value Inn - Bell Tower is a 1-minute drive from Bell Tower Park and 8 minutes from Raccoon Lake Park.  This hotel is 16.1 mi (25.9 km) from Dix Village Hall and 17.1 mi (27.5 km) from Salem Fairgrounds.</p><p><b>Rooms</b> <br />Make yourself at home in one of the 57 guestrooms featuring refrigerators and microwaves. Rooms have private balconies. Complimentary wireless Internet access keeps you connected, and cable programming is available for your entertainment. Private bathrooms have complimentary toiletries and hair dryers.</p><p><b>Amenities</b> <br />Take advantage of recreation opportunities such as an indoor pool, or other amenities including complimentary wireless Internet access and a television in a common area.</p><p><b>Dining</b> <br />A complimentary continental breakfast is served daily.</p><p><b>Business, Other Amenities</b> <br />Featured amenities include a business center, a 24-hour front desk, and an elevator (lift).</p>', '200 East Noleman CentraliaIllinois 62801 ', 259, 2);
